pub(crate) fn first_non_global_arg_idx(
    cmd: &usage_rs::Command<'_>,
    args: &[String],
) -> Option<usize> {
    let flags = get_global_flags(cmd).0;
    first_non_global_arg_idx_with(|f| flags.iter().any(|x| x == f), args)
}

